import{_ as a,C as n,o,c as i,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Deleting a Digital Employee Context Must Revoke Authority and Reconcile Unsettled Work","description":"","frontmatter":{"title":"Deleting a Digital Employee Context Must Revoke Authority and Reconcile Unsettled Work","date":"2026-08-09","column":"digital-employee","category":"daily","summary":"Deleting a Conversation, WorkOrder or other durable work context cannot be reduced to hiding an object from the UI. A governed runtime treats deletion as authority revocation, reconciles all unsettled child work under the same serialization boundary used for admission, and uses worker leases to bound physical execution that has already escaped the database transaction.","item_id":"Q-20260809-01","source_research_object":"research/analysis/Q-20260809-01-revocation-coupled-run-reconciliation.md","source_reading_result":"research/reading/Q-20260809-01-conversation-delete-run-cancellation.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-09-revocation-coupled-run-reconciliation-cover-v2.jpg"},"headers":[],"relativePath":"en/digital-employee/2026-08-09-revocation-coupled-run-reconciliation.md","filePath":"en/digital-employee/2026-08-09-revocation-coupled-run-reconciliation.md","lastUpdated":1787407830000}'),l={name:"en/digital-employee/2026-08-09-revocation-coupled-run-reconciliation.md"};function c(d,e,h,u,p,g){const t=n("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/daily-2026-08-09-revocation-coupled-run-reconciliation-cover-v2.jpg",kicker:"Digital Employee · Daily Research",title:"Deleting a Digital Employee Context Must Revoke Authority and Reconcile Unsettled Work",summary:"Deleting a Conversation, WorkOrder or other durable work context cannot be reduced to hiding an object from the UI. A governed runtime treats deletion as authority revocation, reconciles all unsettled child work under the same serialization boundary used for admission, and uses worker leases to bound physical execution that has already escaped the database transaction.",version:"Q-20260809-01",status:"Daily Runtime V5 · 2026-08-09",languageHref:"/zh/digital-employee/2026-08-09-revocation-coupled-run-reconciliation",languageLabel:"中文"}),e[0]||(e[0]=s(` # Deleting a Digital Employee Context Must Revoke Authority and Reconcile Unsettled Work <p>As Digital Employees take on longer-lived and recoverable work, deleting a Conversation, WorkOrder or business session stops being an ordinary interface operation. The object may disappear from a list immediately while queued tasks, approval waits, running workers and occupied execution slots remain alive.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p><strong>Deleting a durable work context is an authority-revocation event followed by governed reconciliation of every unsettled child task.</strong></p><p>The strongest mechanism is not a cleanup scan that runs after deletion. Admission and revocation should share one durable serialization boundary. That boundary prevents a new child run from slipping through a race during teardown and becoming work that the operator can no longer see or control.</p><p>The sole analytical input for this article is the <code>Q-20260809-01</code> Research Object. Production did not return to the Signal Pool or introduce a new research object.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>This article is based on <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-01-revocation-coupled-run-reconciliation.md" target="_blank" rel="noreferrer">Research Object — Revocation-Coupled Run Reconciliation</a>. Its evidence trail leads to <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-01-conversation-delete-run-cancellation.md" target="_blank" rel="noreferrer">Reading Result — Conversation Delete Run Cancellation</a>.</p><p>The Reading Result records a merged implementation in which conversation deletion handles unsettled runs under the same conversation-row lock used for run admission. This article does not promote that implementation into a generic exactly-once proof for distributed cancellation.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The Research Object separates three states that a single “cancel” control can easily collapse:</p><ul><li><code>QUEUED</code>: no physical worker is executing, so the durable run can be closed synchronously;</li><li><code>AWAITING_APPROVAL</code>: the run remains operationally unsettled even when a storage field such as <code>finishedAt</code> has already been populated;</li><li><code>RUNNING</code>: the transaction can record cancellation intent, but execution outside the transaction can only wind down cooperatively.</li></ul><p>This is why the unsettled set should be defined by business lifecycle semantics rather than a convenient storage predicate.</p><h2 id="mechanism-comparison" tabindex="-1">Mechanism comparison <a class="header-anchor" href="#mechanism-comparison" aria-label="Permalink to &quot;Mechanism comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Approach</th><th style="text-align:right;">Blocks concurrent admission</th><th style="text-align:right;">Covers approval waits</th><th style="text-align:right;">Proves a running worker stopped</th><th style="text-align:right;">Orphan-work risk</th></tr></thead><tbody><tr><td>UI-only hiding</td><td style="text-align:right;">No</td><td style="text-align:right;">No</td><td style="text-align:right;">No</td><td style="text-align:right;">High</td></tr><tr><td>Asynchronous post-delete scan</td><td style="text-align:right;">Unreliable</td><td style="text-align:right;">Depends on predicate</td><td style="text-align:right;">No</td><td style="text-align:right;">Medium to high</td></tr><tr><td>Revocation and reconciliation under one lock</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Records intent only</td><td style="text-align:right;">Low, but lease still required</td></tr><tr><td>Same lock plus worker lease/watchdog</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Governs convergence after lease expiry</td><td style="text-align:right;">Lowest</td></tr></tbody></table><p>The table is a Research Center synthesis based on the Research Object. It does not claim that the selected implementation already ships a complete generic worker-lease system.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>A shared lock establishes an explicit order. Either a run is admitted first and the revocation transaction observes and reconciles it, or revocation completes first and later admission observes the deleted context and is rejected. Without that order, deletion and admission can both succeed independently.</p><p>A database transaction, however, governs durable state rather than physical execution. A worker may already be running on another machine, inside a browser, through an MCP server or against an external tool. Writing <code>cancelRequestedAt</code> does not prove that physical work stopped, nor does it guarantee that a late side effect will never arrive.</p><p>A complete mechanism therefore needs a worker lease:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authority revoked</span></span>
<span class="line"><span>→ cancellation intent persisted</span></span>
<span class="line"><span>→ worker acknowledges within lease</span></span>
<span class="line"><span>→ otherwise lease expires</span></span>
<span class="line"><span>→ stale worker is fenced</span></span>
<span class="line"><span>→ governed recovery may take over</span></span></code></pre></div><p>This is a defining difference between deleting a record and revoking a Digital Employee work context. The latter must reconcile delegated execution capability, not only stored data.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>A Digital Employee runtime should preserve separate events for context revocation, unsettled-set discovery, synchronous closure of queued/approval work, cancellation intent for running workers, worker acknowledgement or lease expiry, slot release and rejection of stale late results.</p><p>For CodeFlowMu, “execution slot opened” must not remain sufficient evidence that a worker is actively progressing. Authoritative Running requires a claim, heartbeat, bounded lease and terminal result.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>The available evidence does not establish a maximum wind-down time for a running worker. It also does not prove exactly-once physical termination under network partition, or define compensation for side effects already emitted to external systems.</p><p>The correct conclusion is therefore not that one transaction solves cancellation. <strong>The transaction makes authority and durable state consistent; a lease/watchdog makes physical execution converge within a governed bound.</strong></p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>The next engineering questions are how to set lease durations by task class, how to fence stale workers after a replacement starts, how to record compensation for external side effects, and how operator surfaces should distinguish “cancellation requested,” “worker stopped,” and “lease expired.”</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The visual shows admission and context revocation sharing one row lock, followed by state-specific treatment of queued/approval work and running workers. The lease watchdog is a Research Center completion of the mechanism, not a capability already demonstrated by the selected source.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-01-revocation-coupled-run-reconciliation.md" target="_blank" rel="noreferrer">Research Object — Revocation-Coupled Run Reconciliation</a>: sole analytical input.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-01-conversation-delete-run-cancellation.md" target="_blank" rel="noreferrer">Reading Result — Conversation Delete Run Cancellation</a>: traceability for implementation facts, limitations and unresolved questions.</li></ol>`,34))])}const b=a(l,[["render",c]]);export{y as __pageData,b as default};
